Context:
- The buffer leaves one slot empty so `head == tail` always means empty and never full.
- Capacity is rounded up to a power of two so indices can wrap using a bitmask.
- `Ordering::Acquire` on the load pairs with the producer's `Release` store, ensuring the consumer sees the slot's written data once it sees the updated tail.

```rust
pub struct Ring<T> {
    slots: Box<[UnsafeCell<MaybeUninit<T>>]>,
    mask: usize,
    head: AtomicUsize,
    tail: AtomicUsize,
}

impl<T> Ring<T> {
    pub fn with_capacity(capacity: usize) -> Self {
        let size = (capacity + 1).next_power_of_two();
        let slots = (0..size).map(|_| UnsafeCell::new(MaybeUninit::uninit())).collect();
        Self { slots, mask: size - 1, head: AtomicUsize::new(0), tail: AtomicUsize::new(0) }
    }

    pub fn pop(&self) -> Option<T> {
        let head = self.head.load(Ordering::Relaxed);
        if head == self.tail.load(Ordering::Acquire) {
            return None;
        }
        let value = unsafe { (*self.slots[head].get()).assume_init_read() };
        self.head.store((head + 1) & self.mask, Ordering::Release);
        Some(value)
    }
}
```

